type OrderStatus = "pending" | "paid" | "shipped" | "delivered" | "cancelled";

function without<T, U extends T>(items: readonly T[], removed: readonly U[]): Exclude<T, U>[] {
  const drop: readonly T[] = removed;
  return items.filter((item): item is Exclude<T, U> => !drop.includes(item));
}

const all: OrderStatus[] = ["pending", "paid", "shipped", "delivered", "cancelled"];
const open = without(all, ["delivered", "cancelled"]);
console.log(open.join(","));

