type Wrapped<T> = {
  readonly [K in keyof T]: T[K] extends (...args: infer A) => infer R ? (...args: A) => Promise<Awaited<R>> : T[K];
};

function wrap(fn: (...args: unknown[]) => unknown): (...args: unknown[]) => Promise<unknown> {
  return async (...args) => fn(...args);
}

function wrapAll<T extends object>(client: T): Wrapped<T> {
  const wrapped: Record<string, unknown> = {};
  const source = client as Record<string, unknown>;
  for (const key of Object.keys(source)) {
    const value = source[key];
    wrapped[key] = typeof value === "function" ? wrap((...args: unknown[]): unknown => value.apply(client, args)) : value;
  }
  return wrapped as Wrapped<T>;
}

const payments = wrapAll({
  baseUrl: "https://api.example-payments.ng",
  feeFor(amountKobo: number): number {
    return Math.min(Math.round(amountKobo * 0.015), 200_000);
  },
});

console.log(await payments.feeFor(1_500_000), payments.baseUrl);

