type PayloadOf<H> = H extends (event: infer E) => void ? E : never;

const handlers = {
  orderPaid: (event: { orderId: string; amountKobo: number }) => console.log("paid", event.orderId, event.amountKobo),
  stockLow: (event: { sku: string; left: number }) => console.log("low", event.sku, event.left),
};

type Handlers = typeof handlers;

function emit<K extends keyof Handlers>(name: K, event: PayloadOf<Handlers[K]>): void {
  const handler = handlers[name] as (event: PayloadOf<Handlers[K]>) => void;
  handler(event);
}

emit("orderPaid", { orderId: "ORD-7", amountKobo: 1_500_000 });
